export function calculateAccrualAmountByPeriod(input: { tariffType?: string | null; tariffAmount?: number | string | null; serviceFrom?: string; serviceTo?: string }) {
  const tariff = Number(input.tariffAmount);
  if (!Number.isFinite(tariff) || tariff <= 0 || !input.serviceFrom || !input.serviceTo || input.serviceFrom > input.serviceTo) return null;
  const from = Date.parse(`${input.serviceFrom}T00:00:00Z`);
  const to = Date.parse(`${input.serviceTo}T00:00:00Z`);
  const days = Math.floor((to - from) / 86400000) + 1;
  const amount = input.tariffType === "daily" ? tariff * days : tariff;
  return Math.round((amount + Number.EPSILON) * 100) / 100;
}

const money = (value: unknown) => `${Number(value ?? 0).toLocaleString("ru-RU", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ₸`;
const normalizeDateOnly = (value: unknown) => { const text = String(value ?? "").trim(); const match = text.match(/^(\d{4}-\d{2}-\d{2})/); return match ? match[1] : ""; }; const dateText = (value: unknown) => value ? new Date(String(value)).toLocaleDateString("ru-RU") : "—";
const dateOnly = (value: unknown) => value instanceof Date ? value.toISOString().slice(0, 10) : String(value ?? "").slice(0, 10);
const quantityUnit = (days: number) => days === 1 ? "день" : days < 5 ? "дня" : "дней"; const accrualDays = (accrual: any) => { const from = dateOnly(accrual.serviceFrom); const to = dateOnly(accrual.serviceTo); return Math.max(0, Math.round((Date.parse(to + "T00:00:00Z") - Date.parse(from + "T00:00:00Z")) / 86400000) + 1); }; const isPartialAccrual = (accrual: any) => { const parts = String(accrual.period ?? "").split("-").map(Number); const year = parts[0]; const month = parts[1]; if (!year || !month) return false; const periodStart = String(year) + "-" + String(month).padStart(2, "0") + "-01"; const periodEndDate = new Date(Date.UTC(year, month, 0)); const periodEnd = String(year) + "-" + String(month).padStart(2, "0") + "-" + String(periodEndDate.getUTCDate()).padStart(2, "0"); return dateOnly(accrual.serviceFrom) !== periodStart || dateOnly(accrual.serviceTo) !== periodEnd; };
