export const getScanMimeType = (file?: Pick<File, "type" | "name">) => { if (!file) return null; const mime = file.type?.toLowerCase(); if (supportedScanMimeTypes.includes(mime as (typeof supportedScanMimeTypes)[number])) return mime as (typeof supportedScanMimeTypes)[number]; const extension = (file.name ?? "").toLowerCase().match(/\.(pdf|jpe?g|png)$/)?.[1]; return extension === "pdf" ? "application/pdf" : extension === "jpg" || extension === "jpeg" ? "image/jpeg" : extension === "png" ? "image/png" : null; }; export const isSupportedScanFile = (file?: Pick<File, "type" | "name">) => Boolean(getScanMimeType(file));
