export function parseMoneyText(value: unknown) {
  if (typeof value === "number") return value;
  const text = String(value ?? "").replace(/[\s\u00a0]/g, "").replace(/[^\d.,-]/g, "").replace(",", ".");
  return text ? Number(text) : Number.NaN;
}
export type BulkContractFields = {
  contractNumber?: string;
  contractDate?: string;
  tenantName: string;
  tenantContact?: string;
  tenantEmail?: string;
  tenantCategory?: string;
  tenantNumber?: string;
  propertyName: string;
  unitName?: string;
  startDate: string;
  endDate: string;
  terminationDate?: string;
  terminationReason?: string;
  blockFolder?: string;
  tariffType: "monthly" | "daily";
  tariffAmount: number;
  tariffSchedule?: Array<{ from: string; to: string; tariffType: "monthly" | "daily"; amount: number; units?: number }>;
  status: "active" | "paused" | "ended";
  notes?: string;
};
export function buildBulkContractFields(preview: any): BulkContractFields {
  return {
    contractNumber: String(preview?.contractNumber ?? "").trim() || undefined,
    contractDate: normalizeDateOnly(preview?.contractDate) || undefined,
    tenantName: String(preview?.tenantName ?? "").trim(),
    tenantContact: String(preview?.tenantContact ?? "").trim() || undefined,
    tenantEmail: String(preview?.tenantEmail ?? "").trim() || undefined,
    tenantCategory: String(preview?.tenantCategory ?? "").trim() || undefined,
    tenantNumber: String(preview?.tenantNumber ?? "").trim() || undefined,
    propertyName: String(preview?.propertyName ?? "").trim(),
    unitName: String(preview?.unitName ?? "").trim() || undefined,
    startDate: normalizeDateOnly(preview?.startDate),
    endDate: normalizeDateOnly(preview?.endDate),
    terminationDate: normalizeDateOnly(preview?.terminationDate) || undefined,
    terminationReason: String(preview?.terminationReason ?? "").trim() || undefined,
    blockFolder: String(preview?.blockFolder ?? "").trim() || undefined,
    tariffType: preview?.tariffType === "daily" ? "daily" : "monthly",
    tariffAmount: parseMoneyText(preview?.tariffAmount),
    tariffSchedule: parseTariffSchedule(preview?.tariffSchedule, preview?.tariffType === "daily" ? "daily" : "monthly"),
    status: preview?.status === "paused" ? "paused" : preview?.status === "ended" ? "ended" : "active",
    notes: String(preview?.notes ?? "").trim() || undefined,
  };
}
export function validateBulkScanPreview(preview: any): string | null {
  const fields = buildBulkContractFields(preview);
  if (!fields.tenantName) return "Не распознан плательщик / арендатор";
  if (!fields.propertyName) return "Не распознан объект";
  if (!fields.startDate || !fields.endDate) return "Не распознан период договора";
  if (fields.startDate > fields.endDate) return "Дата начала не может быть позже даты окончания";
  if (!Number.isFinite(fields.tariffAmount) || fields.tariffAmount <= 0) return "Не распознана ставка";
  const scheduleErrors = validateTariffSchedule(fields.tariffSchedule ?? [], fields);
  if (scheduleErrors.length) return scheduleErrors[0];
  if (fields.terminationDate && (fields.terminationDate < fields.startDate || fields.terminationDate > fields.endDate)) return "Дата расторжения должна быть внутри периода договора";
  const today = new Date().toISOString().slice(0, 10);
  if (fields.status === "ended" && !fields.terminationDate && fields.endDate >= today) return "Для завершённого договора укажите дату окончания или расторжения";
  if (fields.status !== "ended" && !fields.terminationDate && fields.endDate < today) return "Договор с прошедшей датой окончания нужно проверить вручную";
  return null;
}
export const readFileAsDataUrl = (file: File) => new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(new Error("Не удалось прочитать файл скана")); reader.onload = () => resolve(String(reader.result)); reader.readAsDataURL(file as File); });
export type ContractDuplicateMatch = { contract: any; matchedBy: Array<"contractNumber" | "tenantName"> };
export function findContractDuplicates(candidate: any, existingContracts: any[]): ContractDuplicateMatch[] {
  const number = normalizeSearchText(candidate?.contractNumber);
  const tenant = normalizeSearchText(candidate?.tenantName);
  return existingContracts.flatMap(contract => {
    const matchedBy: Array<"contractNumber" | "tenantName"> = [];
    if (number && normalizeSearchText(contract.contractNumber) === number) matchedBy.push("contractNumber");
    if (tenant && areSimilarTenantNames(tenant, normalizeSearchText(contract.tenantName))) matchedBy.push("tenantName");
    return matchedBy.length ? [{ contract, matchedBy }] : [];
  });
}
export function levenshteinDistance(left: string, right: string) {
  const a = Array.from(left); const b = Array.from(right); const row = Array.from({ length: b.length + 1 }, (_, index) => index);
  for (let i = 1; i <= a.length; i++) { let diagonal = row[0]; row[0] = i; for (let j = 1; j <= b.length; j++) { const above = row[j]; row[j] = a[i - 1] === b[j - 1] ? diagonal : Math.min(row[j] + 1, row[j - 1] + 1, diagonal + 1); diagonal = above; } }
  return row[b.length] ?? 0;
}
export function areSimilarTenantNames(left: string, right: string) {
  if (!left || !right) return false;
  if (left === right) return true;
  const shorter = left.length <= right.length ? left : right; const longer = shorter === left ? right : left;
  if (shorter.length < 4) return false;
  if (longer.includes(shorter)) return true;
  return 1 - levenshteinDistance(left, right) / Math.max(left.length, right.length) >= 0.82;
}
export const parseContractIdentityFromFileName = (fileName: string) => { const baseName = fileName.replace(/\.[^.]+$/, "").trim(); const withDate = baseName.match(/^(.*?)\s+(?:от|from)\s+(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})/i); if (withDate) { const year = withDate[4].length === 2 ? `20${withDate[4]}` : withDate[4]; return { contractNumber: withDate[1].replace(/^№\s*/i, "").trim() || null, contractDate: `${year}-${withDate[3].padStart(2, "0")}-${withDate[2].padStart(2, "0")}` }; } const withIsoDate = baseName.match(/^(.*?)\s+(?:от|from)\s+(\d{4})-(\d{1,2})-(\d{1,2})/i); if (withIsoDate) return { contractNumber: withIsoDate[1].replace(/^№\s*/i, "").trim() || null, contractDate: `${withIsoDate[2]}-${withIsoDate[3].padStart(2, "0")}-${withIsoDate[4].padStart(2, "0")}` }; const numberOnly = baseName.match(/^(?:№\s*)?([A-Za-zА-Яа-яЁё0-9][A-Za-zА-Яа-яЁё0-9./_-]*)/); return { contractNumber: numberOnly?.[1] ?? null, contractDate: null }; };
export const countRentersByBlock = (contracts: Array<{ propertyName?: string | null; tenantName?: string | null; tenantEmail?: string | null }>) => { const groups = new Map<string, Set<string>>(); contracts.forEach(contract => { const block = String(contract.propertyName ?? "").trim() || "Без блока"; const renter = String(contract.tenantEmail ?? contract.tenantName ?? "").trim().toLocaleLowerCase("ru-RU") || "без имени"; if (!groups.has(block)) groups.set(block, new Set()); groups.get(block)!.add(renter); }); return Array.from(groups, ([block, renters]) => ({ block, renters: renters.size })).sort((a, b) => a.block.localeCompare(b.block, "ru")); };
export const calculationQuantityLabel = (accrual: any, contract: any) => {
  const from = dateOnly(accrual.serviceFrom);
  const to = dateOnly(accrual.serviceTo);
  const days = Math.max(0, Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86400000) + 1);
  if (contract?.tariffType === "daily") return `${days} ${quantityUnit(days)}`;
  const [year, month] = String(accrual.period).split("-").map(Number);
  const periodStart = `${year}-${String(month).padStart(2, "0")}-01`;
  const periodEndDate = new Date(Date.UTC(year, month, 0));
  const periodEnd = `${year}-${String(month).padStart(2, "0")}-${String(periodEndDate.getUTCDate()).padStart(2, "0")}`;
  return from === periodStart && to === periodEnd ? "1 месяц" : `${days} ${quantityUnit(days)} / 1 месяц`;
};

