export function hasLessThanMonthRemaining(endDate: string | Date, now = new Date()) { const end = new Date(endDate); if (Number.isNaN(end.getTime())) return false; const current = new Date(now); current.setHours(0, 0, 0, 0); end.setHours(0, 0, 0, 0); const threshold = new Date(current); threshold.setMonth(threshold.getMonth() + 1); return end >= current && end < threshold; }
export function shouldReviewOcrField(value: unknown, confidence?: unknown) { return Number(confidence ?? 1) < 0.75 || !String(value ?? "").trim(); }

