  const [form, setForm] = useState(prefill && !contract ? { ...initial, contractNumber: prefill.contractNumber ?? "", contractDate: prefill.contractDate ?? "", tenantName: prefill.tenantName ?? "", tenantContact: prefill.tenantContact ?? "", tenantEmail: prefill.tenantEmail ?? "", tenantCategory: prefill.tenantCategory ?? "", tenantNumber: prefill.tenantNumber ?? "", propertyName: prefill.propertyName ?? "", blockFolder: prefill.blockFolder ?? "", unitName: prefill.unitName ?? "", startDate: prefill.startDate ?? "", endDate: prefill.endDate ?? "", terminationDate: normalizeDateOnly(prefill.terminationDate), terminationReason: prefill.terminationReason ?? "", tariffType: prefill.tariffType ?? "monthly", tariffAmount: prefill.tariffAmount == null ? "" : String(prefill.tariffAmount), status: prefill.status ?? "active" } : initial);
