  const update = trpc.contracts.update.useMutation({ onSuccess: savedContract => { toast.success("Договор обновлён, начисления пересчитываются"); utils.contracts.list.invalidate(); utils.accruals.invalidate(); onDone(savedContract); }, onError: e => toast.error(e.message) });
  const createFromScan = trpc.contracts.createFromScan.useMutation({ onSuccess: savedContract => { toast.success("Договор создан, скан прикреплён"); utils.contracts.list.invalidate(); utils.documents.list.invalidate(); utils.accruals.invalidate(); onDone(savedContract); }, onError: e => toast.error(e.message) });
