  const accrualTotal = accruals.data?.reduce((sum, a) => sum + Number(a.amount), 0) ?? 0;
  const folderNames = folders.data?.map(folder => folder.name) ?? [...BLOCK_FOLDER_OPTIONS];
  const knownFolderNames = Array.from(new Set([...folderNames, ...(contracts.data ?? []).map(contract => String(contract.blockFolder ?? "").trim()).filter(Boolean)]));
  const blockSummary = knownFolderNames.map(folder => ({ block: folder, renters: (contracts.data ?? []).filter(contract => String(contract.blockFolder ?? "").trim() === folder).length })).filter(item => item.renters > 0);
